package ai.decisionos.aside;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.util.*;
/** Durable reminders and read-only portal refreshes. Never represents an external submission. */
final class ScheduledWorkStore extends SQLiteOpenHelper {
 ScheduledWorkStore(Context c){super(c,"nubi_scheduled_work.db",null,4);}
 public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE work (id TEXT PRIMARY KEY,goal_id TEXT NOT NULL,title TEXT NOT NULL,prompt TEXT NOT NULL,kind TEXT NOT NULL,url TEXT NOT NULL,due_at INTEGER NOT NULL,state TEXT NOT NULL,created_at INTEGER NOT NULL,fired_at INTEGER NOT NULL DEFAULT 0,dispatch_count INTEGER NOT NULL DEFAULT 0,detail TEXT NOT NULL DEFAULT '',precision TEXT NOT NULL DEFAULT '',notification TEXT NOT NULL DEFAULT '')");db.execSQL("CREATE INDEX work_due ON work(state,due_at)");onUpgrade(db,1,4);}
 public void onUpgrade(SQLiteDatabase db,int old,int next){if(old<4)for(String column:new String[]{"repeat_rule","series_id","next_id"})db.execSQL("ALTER TABLE work ADD COLUMN "+column+" TEXT NOT NULL DEFAULT ''");if(old<2)for(String column:new String[]{"conversation_id","request_id","job_id"})db.execSQL("ALTER TABLE work ADD COLUMN "+column+" TEXT NOT NULL DEFAULT ''");if(old<3)for(String column:new String[]{"room_type","group_goals"})db.execSQL("ALTER TABLE work ADD COLUMN "+column+" TEXT NOT NULL DEFAULT ''");}
 static boolean kind(String k){return Arrays.asList("reminder","portal_refresh","zoom").contains(k);}
 String create(String goal,String title,String prompt,String kind,String url,long due,long now){if(!goal.matches("[0-9a-f-]{36}")||title.isBlank()||title.length()>150||prompt.length()>1500||!kind(kind)||due<=now||due-now>366L*86400000||(!url.isEmpty()&&!ScheduledWork.zoomUrl(url)))throw new IllegalArgumentException("예약 제목·날짜·연결 주소를 확인해 주세요");try(Cursor count=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM work WHERE state NOT IN ('ACKNOWLEDGED','CANCELLED','RESULT_READY','FAILED')",null)){count.moveToFirst();if(count.getInt(0)>=100)throw new IllegalArgumentException("먼저 이전 예약을 확인하거나 취소해 주세요");}String id=UUID.randomUUID().toString();ContentValues v=new ContentValues();v.put("id",id);v.put("goal_id",goal);v.put("title",title);v.put("prompt",prompt);v.put("kind",kind);v.put("url",url);v.put("due_at",due);v.put("state","SCHEDULED");v.put("created_at",now);getWritableDatabase().insertOrThrow("work",null,v);return id;}
 JSONObject get(String id){try(Cursor c=getReadableDatabase().rawQuery("SELECT * FROM work WHERE id=?",new String[]{id})){return c.moveToFirst()?row(c):new JSONObject();}}
 static JSONObject row(Cursor c){JSONObject r=new JSONObject();for(int n=0;n<c.getColumnCount();n++){String key=c.getColumnName(n);GoalStore.put(r,key,c.getType(n)==Cursor.FIELD_TYPE_INTEGER?c.getLong(n):c.getString(n));}return r;}
 List<JSONObject> list(){List<JSONObject> out=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT * FROM work WHERE state NOT IN ('CANCELLED','ACKNOWLEDGED') ORDER BY CASE state WHEN 'CHAT_RUNNING' THEN 0 WHEN 'CHAT_QUEUED' THEN 1 WHEN 'READY' THEN 2 WHEN 'SCHEDULED' THEN 3 ELSE 4 END,CASE WHEN state IN ('RESULT_READY','FAILED') THEN -created_at ELSE due_at END LIMIT 100",null)){while(c.moveToNext())out.add(row(c));}return out;}
 boolean claim(String id,long now){ContentValues v=new ContentValues();v.put("state","READY");v.put("fired_at",now);v.put("dispatch_count",1);return getWritableDatabase().update("work",v,"id=? AND state='SCHEDULED' AND due_at<=?",new String[]{id,Long.toString(now)})==1;}
 boolean state(String id,String from,String to,String detail){ContentValues v=new ContentValues();v.put("state",to);v.put("detail",detail);return getWritableDatabase().update("work",v,"id=? AND state=?",new String[]{id,from})==1;}
 void metadata(String id,String key,String value){if(!Arrays.asList("precision","notification","conversation_id","request_id","job_id","room_type","group_goals","repeat_rule","series_id","next_id").contains(key))throw new IllegalArgumentException();ContentValues v=new ContentValues();v.put(key,value);getWritableDatabase().update("work",v,"id=?",new String[]{id});}
 String repeatNext(String id,long now){SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{JSONObject r=get(id);String rule=r.optString("repeat_rule");if(rule.isEmpty()||r.optString("state").equals("CANCELLED"))return "";if(!r.optString("next_id").isEmpty())return r.optString("next_id");String next=create(r.optString("goal_id"),r.optString("title"),r.optString("prompt"),r.optString("kind"),r.optString("url"),ChatTime.next(r.optLong("due_at"),rule,now),now);for(String key:new String[]{"conversation_id","room_type","group_goals","repeat_rule","series_id"})metadata(next,key,r.optString(key));metadata(id,"next_id",next);db.setTransactionSuccessful();return next;}finally{db.endTransaction();}}
 List<String> waiting(){List<String> ids=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT id FROM work WHERE state='REFRESH_QUEUED'",null)){while(c.moveToNext())ids.add(c.getString(0));}return ids;}
}
